let Q=[];
function pages(s){c.font=`16px ${FONT}`;const lines=[];
 for(const para of s.split('\n')){let cur='';for(const ch of para){if(c.measureText(cur+ch).width>280){const sp=cur.lastIndexOf(' ');if(sp>0){lines.push(cur.slice(0,sp));cur=cur.slice(sp+1)+ch}else{lines.push(cur);cur=ch}}else cur+=ch}lines.push(cur)}
 const out=[];for(let i=0;i<lines.length;i+=2)out.push(lines.slice(i,i+2));return out}
const T=(...ss)=>[].concat(...ss.map(s=>pages(s).map(m=>({m,n:0}))));
const F=f=>({f});
const Wt=w=>({w});
const delay=n=>{let k=0;return Wt(()=>++k>n)};
function say(...ss){Q.push(...T(...ss))}
function stepQ(){let g=0;while(Q.length&&g++<300){const s=Q[0];
 if(s.f){Q.shift();const r=s.f();if(r&&r.length)Q.unshift(...r);continue}
 if(s.learn){const r=updLearn(s.learn);if(r){Q.shift();Q.unshift(...r);continue}return}
 if(s.w){if(s.w()){Q.shift();continue}return}
 const len=s.m.join('').length;
 if(s.n<len){s.n+=held.a?5:2;if(btnp('a'))s.n=len;return}
 if(btnp('a')||btnp('b')){Q.shift();continue}
 return}}

