let boxui=null;
function openBox(){boxui={col:0,i:0,j:0}}
function updBox(){const P0=S.party,BX=S.box,u=boxui;
 if(btnp('left')||btnp('right')){u.col^=1;AU.sfx('cur')}
 const L=u.col===0?P0:BX,k=u.col===0?'i':'j',n=L.length;
 if(n){if(btnp('up')){u[k]=(u[k]+n-1)%n;AU.sfx('cur')}if(btnp('down')){u[k]=(u[k]+1)%n;AU.sfx('cur')}}
 if(btnp('b')){boxui=null;save();say('クラウドたんまつを とじた。');return}
 if(!btnp('a')||!n)return;
 if(u.col===0){if(!P0.some((x,idx)=>idx!==u.i&&x.hp>0)){say('たたかえる モンスターが\nいなくなって しまう！');return}
  if(BX.length>=120){say('クラウドBOXが いっぱいだ！');return}
  const m=P0.splice(u.i,1)[0];m.hp=m.mhp;m.status=null;m.slp=0;BX.push(m);u.i=Math.max(0,Math.min(u.i,P0.length-1));AU.sfx('buy');save();say(`${nm(m)}を クラウドBOXに\nあずけた！`)}
 else{if(P0.length>=6){say('てもちが いっぱいだ！\nさきに だれかを あずけよう。');return}
  const m=BX.splice(u.j,1)[0];P0.push(m);u.j=Math.max(0,Math.min(u.j,BX.length-1));AU.sfx('buy');save();say(`${nm(m)}を\nてもちに ひきだした！`)}}
