 if(m){const sp=SP[m.id];R(20,234,46,14,TCOL[sp.type]||'#888');txt(TN[sp.type],43,236,'#ffffff',9,'center');txt(`${nm(m)}　Lv${m.lv}　HP ${m.hp}/${m.mhp}`,74,234,3,12)}
